import React, { useState, useEffect, useRef } from 'react';
import { Card, api } from '../App';

export default function ReportsPage() {
  const [saleNos,      setSaleNos]      = useState([]);
  const [selSale,      setSelSale]      = useState('');
  const [activeTab,    setActiveTab]    = useState('party');
  const [partyData,    setPartyData]    = useState([]);
  const [expanded,     setExpanded]     = useState(null);
  const [loadingParty, setLoadingParty] = useState(false);
  const [marketData,   setMarketData]   = useState([]);
  const [mktGrade,     setMktGrade]     = useState('');
  const [loadingMkt,   setLoadingMkt]   = useState(false);
  const printRef = useRef(null);

  useEffect(() => {
    api.get('/import/sale-numbers')
      .then(r => { setSaleNos(r.data); if (r.data[0]) setSelSale(String(r.data[0].sale_no)); })
      .catch(() => {});
  }, []);

  const loadPartyReport = async () => {
    if (!selSale) return;
    setLoadingParty(true);
    try { const r = await api.get(`/reports/party-summary?sale_no=${selSale}`); setPartyData(r.data); }
    catch (e) { alert(e.response?.data?.error || e.message); }
    finally { setLoadingParty(false); }
  };

  const loadMarketReport = async () => {
    if (!selSale) return;
    setLoadingMkt(true);
    try { const r = await api.get(`/reports/market?sale_no=${selSale}`); setMarketData(r.data); }
    catch (e) { alert(e.response?.data?.error || e.message); }
    finally { setLoadingMkt(false); }
  };

  useEffect(() => {
    if (!selSale) return;
    if (activeTab === 'party')  loadPartyReport();
    if (activeTab === 'market') loadMarketReport();
  }, [selSale, activeTab]); // eslint-disable-line

  const grades = [...new Set(marketData.map(r => r.grade))].sort();
  const filteredMarket = mktGrade ? marketData.filter(r => r.grade === mktGrade) : marketData;
  const mktByGrade = {};
  filteredMarket.forEach(row => {
    if (!mktByGrade[row.grade]) mktByGrade[row.grade] = [];
    mktByGrade[row.grade].push(row);
  });

  const downloadPartyPDF = () => {
    const win = window.open('', '_blank');
    const rowsHtml = partyData.map(party => {
      const lotsRows = (party.lots || []).map((lot, i) => `
        <tr style="background:${i%2===0?'#fff':'#f9fafb'}">
          <td>${lot.garden || ''}</td>
          <td>${lot.origin || ''}</td>
          <td><span class="grade">${lot.grade || ''}</span></td>
          <td>${lot.broker || ''}</td>
          <td style="font-family:monospace">${lot.invoice || ''}</td>
          <td>${lot.bags || ''}</td>
          <td>${lot.net_wt || ''}</td>
          <td style="text-align:right;font-weight:bold;color:#1a7a4a">${lot.price ? '\u20B9' + parseFloat(lot.price).toFixed(0) : ''}</td>
        </tr>`).join('');
      return `
        <div class="party-block">
          <div class="party-hdr">
            <span class="pcode">${party.party_code}</span>
            <span class="pname">${party.party_name}</span>
            <span class="plots">${party.total_lots} lots</span>
          </div>
          <table>
            <thead><tr><th>Garden</th><th>Origin</th><th>Grade</th><th>Broker</th><th>Invoice</th><th>Bags</th><th>Net Wt</th><th>Price \u20B9</th></tr></thead>
            <tbody>${lotsRows}</tbody>
          </table>
        </div>`;
    }).join('');

    win.document.write(`<!DOCTYPE html><html><head><title>Party Report - Sale #${selSale}</title>
<style>
  body { font-family: Arial, sans-serif; font-size: 10px; margin: 15mm; color: #1a2533; }
  h1 { font-size: 14px; color: #1a3c5e; margin-bottom: 3px; }
  .party-block { margin-bottom: 10px; page-break-inside: avoid; }
  .party-hdr { background: #1a3c5e; color: #fff; padding: 4px 10px; display: flex; align-items: center; gap: 10px; border-radius: 3px 3px 0 0; }
  .pcode { background: rgba(255,255,255,0.2); padding: 1px 6px; border-radius: 8px; font-weight: 900; font-size: 11px; }
  .pname { font-weight: 700; font-size: 12px; flex: 1; }
  .plots { font-size: 10px; opacity: 0.8; }
  table { width: 100%; border-collapse: collapse; font-size: 9px; border: 1px solid #e2e8f0; }
  th { background: #f0f4f8; padding: 4px 6px; text-align: left; font-weight: 700; color: #444; }
  td { padding: 3px 6px; border-bottom: 1px solid #f0f4f8; }
  .grade { background: #dbeafe; color: #1e40af; padding: 1px 5px; border-radius: 8px; font-weight: 800; font-size: 8px; }
  @page { size: A4; margin: 10mm; }
  @media print { body { -webkit-print-color-adjust: exact; print-color-adjust: exact; } }
</style></head><body>
<h1>Party Marking Report &mdash; Sale #${selSale}</h1>
<p style="color:#888;font-size:9px;margin-bottom:8px;">Generated: ${new Date().toLocaleString('en-IN')} &nbsp;|&nbsp; ${partyData.length} parties</p>
${rowsHtml}
</body></html>`);
    win.document.close();
    win.focus();
    setTimeout(() => { win.print(); win.close(); }, 500);
  };

  const downloadPDF = () => {
    const content = printRef.current;
    if (!content) return;
    const printWindow = window.open('', '_blank');
    const html = `<!DOCTYPE html>
<html><head><title>Market Report - Sale #${selSale}</title>
<style>
  body { font-family: Arial, sans-serif; font-size: 11px; margin: 20px; color: #1a2533; }
  h1 { font-size: 16px; color: #1a3c5e; }
  h2 { font-size: 13px; color: #1a3c5e; margin: 14px 0 6px; padding: 4px 8px; background: #f0f4f8; }
  table { width: 100%; border-collapse: collapse; margin-bottom: 14px; }
  th { background: #1a3c5e; color: #fff; padding: 5px 8px; text-align: left; font-size: 11px; }
  th.right { text-align: right; }
  td { padding: 4px 8px; border-bottom: 1px solid #e2e8f0; font-size: 11px; }
  td.right { text-align: right; font-weight: bold; }
  tr:nth-child(even) { background: #f8fafc; }
  .low { color: #1a7a4a; }
